/** Parsed once per icon on first use. */
private val UiPackCache = HashMap<OwnTVIcon, Path>()

/** The pack's outline for [icon] in the 24-unit grid, or null when the pack has no glyph for it. */
internal fun uiPackPath(icon: OwnTVIcon): Path? {
    val data = UiPackData[icon] ?: return null
    return UiPackCache.getOrPut(icon) { PathParser().parsePathString(data).toPath() }
}
